using System;
using System.IO;
using System.Collections.Generic;
using CosmicBlock.Core;
using CosmicBlock.UI;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
public static class CollectionMeshProbe {
 static double began;static int frames,count;static string errors="",warnings="";static GameSession session;static GameFlowController flow;static PlanetCollectionView view;static Dictionary<string,int> saved=new Dictionary<string,int>();static List<string> keys=new List<string>(),results=new List<string>();
 public static void Run(){RunSaveStore.PathOverride=Path.GetFullPath("Validation/collection-mesh-isolated.json");keys.Add(GameSession.DefaultBestScoreKey);keys.Add(PlanetSelection.Key);keys.Add(PlanetRestoration.VersionKey);foreach(var d in PlanetDefinitions.All){keys.Add(d.EnergyKey);keys.Add(d.UnlockKey);keys.Add(PlanetCompletionNotice.Key(d.Id));}foreach(var k in keys){if(PlayerPrefs.HasKey(k))saved[k]=PlayerPrefs.GetInt(k);PlayerPrefs.DeleteKey(k);}PlayerPrefs.SetInt(PlanetRestoration.VersionKey,2);PlayerPrefs.SetInt(GameSession.DefaultBestScoreKey,19000);PlayerPrefs.Save();EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");began=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void Check(){if(EditorApplication.timeSinceStartup-began>240){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<40)return;EditorApplication.update-=Check;try{RunSaveStore.PathOverride=Path.GetFullPath("Validation/collection-mesh-isolated.json");RunSaveStore.Delete();session=UnityEngine.Object.FindAnyObjectByType<GameSession>();flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();view=flow.CollectionView;Tests();Finish(errors.Length==0&&warnings.Length==0,errors+warnings);}catch(Exception e){Finish(false,e.ToString());}}
 static void Tests(){flow.ShowHome();flow.HomeRoot.transform.Find("MainActions/PlanetCollectionButton").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Collection,"HOME 실제 도감 버튼");Req(view.PlanetIndex==0&&!view.transform.Find("Previous").GetComponent<Button>().interactable,"첫 행성 Previous 비활성");view.Next();Req(view.PlanetIndex==1&&!view.CanSelect&&view.Status.Contains("잠겨"),"잠긴 행성 데이터");foreach(int h in new[]{1920,2400,1440})Capture(h,"locked2");view.Preview(5);Req(view.PreviewStage==1,"잠긴 단계 미리보기 차단");
  foreach(var d in PlanetDefinitions.All)PlayerPrefs.SetInt(d.UnlockKey,1);
  for(int id=1;id<=5;id++){var d=PlanetDefinitions.Get(id);foreach(float v in new[]{0f,.25f,.5f,.75f,.99f,1f}){PlayerPrefs.SetInt(d.EnergyKey,Mathf.RoundToInt(d.Total*v));view.SelectPlanet(id-1);view.GetComponent<CollectionMeshPresentation>().Sync();Req(view.CanSelect,"해금 행성 "+id);Req(view.Percentage==Mathf.FloorToInt(v*100)+"%"&&Mathf.Abs(view.Progress-v)<.001f,"복원도/실제 Fill "+id+" "+v);var fill=(RectTransform)view.transform.Find("ProgressFrameArea/ProgressFrame/Progress/Fill");Req(fill.GetComponentInChildren<HomeQuitMeshGraphic>()!=null&&Mathf.Abs(fill.anchorMax.x-v)<.001f,"실제 메시 게이지 폭");Req(view.HeroSprite==PlanetArtCatalog.Current.Sprite(id,view.PreviewStage),"기존 Hero Sprite "+id);for(int stage=1;stage<=5;stage++){Req(view.Slots[stage-1].interactable==!view.IsStageLocked(stage),"단계 Hit 상태");Req(view.Slots[stage-1].transform.Find("CurrentRing").gameObject.activeSelf==(stage==view.CurrentStage),"현재 단계 강조");}view.Preview(1);Req(view.PreviewStage==1&&view.HeroSprite==PlanetArtCatalog.Current.Sprite(id,1),"이전 단계 Sprite 미리보기");Req(PlayerPrefs.GetInt(d.EnergyKey)==Mathf.RoundToInt(d.Total*v),"미리보기 Save 불변");view.SelectPlanet(id-1);}
   foreach(int h in new[]{1920,2400,1440})Capture(h,"planet"+id+"_complete");results.Add("PASS 행성 "+id+" 0/25/50/75/99/100 Fill·Sprite·단계·저장");}
  Req(!view.transform.Find("Next").GetComponent<Button>().interactable,"마지막 Next 비활성");PlayerPrefs.SetInt(PlanetDefinitions.Get(1).EnergyKey,1125);view.SelectPlanet(0);foreach(int h in new[]{1920,2400,1440})Capture(h,"planet1_75");view.transform.Find("Back").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Home,"Back HOME");flow.Play();session.DebugSetScore(230);session.SaveCurrentRun();flow.ShowHome();string disk=File.ReadAllText(RunSaveStore.SavePath);flow.ShowCollection();view.SelectPlanet(1);view.Preview(1);view.GoBack();Req(File.ReadAllText(RunSaveStore.SavePath)==disk&&session.Score==230&&session.BestScore==19000,"도감 조회 Run/SCORE/BEST 불변");flow.ShowCollection();view.SelectPlanet(1);view.transform.Find("SelectPlanet").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Game&&session.Score==230&&session.Restoration.PlanetId==2,"기존 선택/Run 이어하기");results.Add("PASS HOME/Back/해금 행성 선택 및 Run 유지");
 }
 static void Capture(int h,string name){var root=(RectTransform)view.transform;var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var safe=(RectTransform)root.parent;var sa=safe.GetComponent<SafeArea>();var cam=Camera.main;var rt=new RenderTexture(1080,h,24);var mode=canvas.renderMode;var camera=canvas.worldCamera;var target=cam.targetTexture;var active=RenderTexture.active;bool enabled=sa.enabled,ortho=cam.orthographic;float size=cam.orthographicSize;var min=safe.anchorMin;var max=safe.anchorMax;Texture2D tex=null;
  try{sa.enabled=false;rt.Create();cam.targetTexture=rt;cam.orthographic=true;cam.orthographicSize=h/2f;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;safe.anchorMin=h==2400?new Vector2(.02f,.04f):Vector2.zero;safe.anchorMax=h==2400?new Vector2(.98f,.94f):Vector2.one;safe.offsetMin=safe.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();view.SelectPlanet(view.PlanetIndex);view.GetComponent<CollectionMeshPresentation>().Sync();Canvas.ForceUpdateCanvases();var bg=(RectTransform)root.Find("Background");var sprite=bg.GetComponent<Image>().sprite;var full=(RectTransform)canvas.transform;bg.sizeDelta=sprite.rect.size*Mathf.Max(full.rect.width/sprite.rect.width,full.rect.height/sprite.rect.height);bg.anchoredPosition=root.InverseTransformPoint(full.TransformPoint(full.rect.center));
   var bounds=World(safe);foreach(string p in new[]{"Title","NameFrameArea","Hero","ProgressFrameArea","Status","StageArea","MessageFrameArea","SelectPlanet","Back","Previous","Next"})Req(Inside(bounds,World((RectTransform)root.Find(p))),"SafeArea "+p+" "+h);Req(!World((RectTransform)root.Find("StageArea")).Overlaps(World((RectTransform)root.Find("MessageFrameArea"))),"단계/메시지 겹침 없음");Req(!World((RectTransform)root.Find("MessageFrameArea")).Overlaps(World((RectTransform)root.Find("SelectPlanet"))),"메시지/선택 겹침 없음");
   foreach(var label in view.GetComponentsInChildren<TextMeshProUGUI>(true)){label.ForceMeshUpdate();Req(label.font.HasCharacters(label.text)&&!label.isTextOverflowing,"TMP 글리프/잘림 "+label.transform.parent.name+" "+h);}
   foreach(string p in new[]{"NameFrameArea/NameFrame","ProgressFrameArea/ProgressFrame","StageArea/FrameArea/Frame","MessageFrameArea/MessageFrame"})Req(root.Find(p).GetComponent<Image>().color.a==0,"PNG 프레임 숨김");
   cam.Render();foreach(string p in new[]{"Back","Previous","Next","SelectPlanet"}){var t=root.Find(p);Req(t.GetComponent<Button>().targetGraphic is HomeQuitMeshGraphic,"메시 버튼 연결");var r=(RectTransform)t;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(cam,r.TransformPoint(r.rect.center))},hits);Req(hits.Count>0&&hits[0].gameObject.transform.IsChildOf(t),"실제 Hit "+p);}
   RenderTexture.active=rt;tex=new Texture2D(1080,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1080,h),0,0);tex.Apply();File.WriteAllBytes("Validation/collection_mesh_"+name+"_"+h+".png",tex.EncodeToPNG());results.Add("PASS "+h+" "+name+" SafeArea/TMP/프레임/터치");
  }finally{canvas.renderMode=mode;canvas.worldCamera=camera;cam.targetTexture=target;cam.orthographic=ortho;cam.orthographicSize=size;RenderTexture.active=active;safe.anchorMin=min;safe.anchorMax=max;sa.enabled=enabled;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 }
 static Rect World(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}static bool Inside(Rect a,Rect b)=>b.xMin>=a.xMin-.1f&&b.yMin>=a.yMin-.1f&&b.xMax<=a.xMax+.1f&&b.yMax<=a.yMax+.1f;
 static void Req(bool v,string s){count++;if(!v)throw new Exception(s);}static void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings+=m+"\n";if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}
 static void Finish(bool pass,string failure){EditorApplication.update-=Check;Application.logMessageReceived-=Log;if(session!=null)session.LeaveForHome();RunSaveStore.Delete();foreach(var k in keys){if(saved.TryGetValue(k,out int v))PlayerPrefs.SetInt(k,v);else PlayerPrefs.DeleteKey(k);}PlayerPrefs.Save();File.WriteAllText("Validation/collection_mesh_tests.txt",string.Join("\n",results)+"\nAssertions="+count+"\nWarnings="+warnings+"\nErrors="+errors+"\n"+(pass?"COLLECTION_MESH_PASS":failure));EditorApplication.Exit(pass?0:1);}
}
